// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#include "StdAfx.h"#include "StandardGraphicsPipeline.h"#include "ShadowMap.h"#include "SceneGBuffer.h"#include "SceneDepth.h"#include "SceneForward.h"#include "Sky.h"#include "SceneCustom.h"#include "AutoExposure.h"#include "Bloom.h"#include "HeightMapAO.h"#include "ScreenSpaceObscurance.h"#include "ScreenSpaceReflections.h"#include "ScreenSpaceSSS.h"#include "VolumetricFog.h"#include "Fog.h"#include "VolumetricClouds.h"#include "Water.h"#include "MotionBlur.h"#include "DepthOfField.h"#include "SunShafts.h"#include "ToneMapping.h"#include "PostAA.h"#include "ComputeSkinning.h"#include "GpuParticles.h"#include "ClipVolumes.h"#include "DeferredDecals.h"#include "ShadowMask.h"#include "TiledShading.h"#include "ColorGrading.h"#include "WaterRipples.h"#include "LensOptics.h"#include "PostEffects.h"#include "Rain.h"#include "Snow.h"#include "MobileComposition.h"#include "OmniCamera.h"#include "TiledLightVolumes.h"#include "DebugRenderTargets.h"#include "Common/TypedConstantBuffer.h"#include "Common/Textures/TextureHelpers.h"#include "Common/Include_HLSL_CPP_Shared.h"#include "../Common/RenderView.h"#include "Common/RenderDisplayContext.h"#include "../D3DPostProcess.h"#include "Common/ReverseDepth.h"#include "D3D_SVO.h"CStandardGraphicsPipeline::CStandardGraphicsPipeline(const IRenderer::SGraphicsPipelineDescription& desc, const std::string& uniqueIdentifier, const SGraphicsPipelineKey key)	: CGraphicsPipeline(desc, uniqueIdentifier, key){}void CStandardGraphicsPipeline::Init(){	MEMSTAT_CONTEXT(EMemStatContextType::Other, "CStandardGraphicsPipeline::Init");	// Register all other stages that don't need the global PSO cache	RegisterStage<CSceneCustomStage>();	RegisterStage<CHeightMapAOStage>();	RegisterStage<CScreenSpaceObscuranceStage>();	RegisterStage<CScreenSpaceReflectionsStage>();	RegisterStage<CScreenSpaceSSSStage>();	RegisterStage<CVolumetricCloudsStage>();	RegisterStage<CWaterRipplesStage>();	RegisterStage<CMotionBlurStage>();	RegisterStage<CDepthOfFieldStage>();	RegisterStage<CAutoExposureStage>();	RegisterStage<CBloomStage>();	RegisterStage<CToneMappingStage>();	RegisterStage<CSunShaftsStage>();	RegisterStage<CPostAAStage>();	RegisterStage<CComputeSkinningStage>();	RegisterStage<CComputeParticlesStage>();	RegisterStage<CDeferredDecalsStage>();	RegisterStage<CShadowMaskStage>();	RegisterStage<CTiledShadingStage>();	RegisterStage<CWaterStage>(); // Has a custom PSO cache like Forward	RegisterStage<CLensOpticsStage>();	RegisterStage<CColorGradingStage>();	RegisterStage<CPostEffectStage>();	RegisterStage<CRainStage>();	RegisterStage<CSnowStage>();	RegisterStage<CSceneDepthStage>();	RegisterStage<COmniCameraStage>();	RegisterStage<CVolumetricFogStage>();	// Register and initialize all common stages	CGraphicsPipeline::Init();	// Out-of-pipeline passes for display	m_HDRToFramePass.reset(new CStretchRectPass(this));	m_PostToFramePass.reset(new CStretchRectPass(this));	m_FrameToFramePass.reset(new CStretchRectPass(this));	m_HQSubResPass[0].reset(new CStableDownsamplePass(this));	m_HQSubResPass[1].reset(new CStableDownsamplePass(this));	m_LQSubResPass[0].reset(new CStretchRectPass(this));	m_LQSubResPass[1].reset(new CStretchRectPass(this));	// eFlags_ReflectConstantBuffersFromShader is NOT optional here, and its absence was the crash	// of 2026-08-28 (EXCEPTION_ACCESS_VIOLATION reading 0x4 on the RenderThread, first frame after	// the Scene Referred checkbox was ticked). Without the flag CComputeRenderPass never calls	// SDeviceObjectHelpers::CShaderConstantManager::AllocateShaderReflection(), so	// m_pShaderReflection stays null; BeginConstantUpdate() then does nothing at all and	// SetConstant() walks straight into SetNamedConstantArray(), whose first act is to read	// m_pShaderReflection->bValid - offset +4 of a null pointer (DeviceObjectHelpers.h:505-507,	// DeviceObjectHelpers.cpp:448). The CRY_ASSERT above that read is compiled out in Profile, so	// the only symptom is the access violation. Every other compute pass in the tree that names a	// constant sets this flag (TiledShading.cpp:16, VolumetricFog.cpp:157, ComputeSkinning.cpp:84,	// CSvoComputePass in D3D_SVO.h:15); ExecuteSceneReferredConversion() names SceneReferredParams,	// so it must too.	m_SceneReferredConvertPass.reset(new CComputeRenderPass(this, CComputeRenderPass::eFlags_ReflectConstantBuffersFromShader));	m_ResolvePass.reset(new CStretchRectPass(this));	m_DownscalePass.reset(new CDownsamplePass(this));	m_UpscalePass.reset(new CSharpeningUpsamplePass(this));	m_AnisoVBlurPass.reset(new CAnisotropicVerticalBlurPass(this));	m_bInitialized = true;}//////////////////////////////////////////////////////////////////////////void CStandardGraphicsPipeline::Resize(int renderWidth, int renderHeight){	CGraphicsPipeline::Resize(renderWidth, renderHeight);}//////////////////////////////////////////////////////////////////////////void CStandardGraphicsPipeline::ShutDown(){	m_bInitialized = false;	CGraphicsPipeline::ShutDown();	CGraphicsPipeline::SetCurrentRenderView(nullptr);	m_HDRToFramePass.reset();	m_PostToFramePass.reset();	m_FrameToFramePass.reset();	m_HQSubResPass[0].reset();	m_HQSubResPass[1].reset();	m_LQSubResPass[0].reset();	m_LQSubResPass[1].reset();	m_SceneReferredConvertPass.reset();	m_ResolvePass.reset();	m_DownscalePass.reset();	m_UpscalePass.reset();}//////////////////////////////////////////////////////////////////////////void CStandardGraphicsPipeline::Update(EShaderRenderingFlags renderingFlags){	FUNCTION_PROFILER_RENDERER();	m_numInvalidDrawcalls = 0;	GenerateMainViewConstantBuffer();	if (!m_changedCVars.GetCVars().empty())	{		CGraphicsPipeline::OnCVarsChanged(m_changedCVars);		m_changedCVars.Reset();	}#if DURANGO_USE_ESRAM	if (!CRendererResources::s_ptexNormalsFitting->IsESRAMResident())		CRendererResources::s_ptexNormalsFitting->AcquireESRAMResidency(CDeviceResource::eResCoherence_Transfer);	if (!CRendererResources::s_ptexPerlinNoiseMap->IsESRAMResident())		CRendererResources::s_ptexPerlinNoiseMap->AcquireESRAMResidency(CDeviceResource::eResCoherence_Transfer);	GetCurrentRenderView()->GetDepthTarget()->AcquireESRAMResidency(CDeviceResource::eResCoherence_Uninitialize);#endif	m_renderingFlags = renderingFlags;	CGraphicsPipeline::Update(renderingFlags);}//////////////////////////////////////////////////////////////////////////// The entry to the scene-referred working space (SceneReferredSpec.md D5, Stage S3;// scene-notes/decisions/s3-working-space.md approach 1A).//// WHY HERE. Between the $HDRTargetPrev copy and the depth-of-field stage is the only window in// the frame where two things are true at once: every writer of Rec.709 scene colour has finished// (deferred and forward opaque, sky, ocean caustics, volumetric fog, global fog, clouds, water,// transparents, half-res particles, snow displacement and the rain layer), and nothing has read// the target for post yet. Converting earlier would leave the rain layer authoring 709 into an// AP1 target; converting later would mean depth of field had already run on mixed data.//// WHY IN PLACE. Each thread reads and writes only its own texel, so there is no cross-texel// dependency and no race: no scratch target, no copy-back and no pipeline pointer to swap. The// pixel-shader form of the same point costs TWO full-screen passes, because a render target// cannot be its own shader resource. $HDRTarget already carries FT_USAGE_UNORDERED_ACCESS// (CTiledShadingStage writes it through SetOutputUAV), so no plumbing is new here.//// If the typed UAV load of R16G16B16A16_FLOAT ever proves unavailable on some target hardware,// the documented fallback is decisions/s3-working-space.md approach 1B: a full-screen pixel pass// into $SceneTargetR11G11B10F[0] (which is dead at this point in the frame) and a copy back.//// WHY NOT AT THE WRITERS. A 3x3 is linear, so additive and alpha blending commute with it and// anything that blended before this point lands in the same place either way. Multiplicative and// min/max blends do NOT commute, and GS_BLSRC_DSTCOL / GS_BLDST_SRCCOL are reachable from// material shader scripts. Converting after all scene blending makes the question moot.void CStandardGraphicsPipeline::ExecuteSceneReferredConversion(){	// IsSceneReferredWorkingSpace() is IsSceneReferred() minus r_SceneReferredDebug 1, which	// leaves the frame in Rec.709 while the rest of the scene-referred pipeline keeps running -	// the A/B that separates "the primaries moved" from everything else this pipeline changed.	// The per-view luminance weights follow the same gate, so the A/B is coherent.	if (!CRendererResources::IsSceneReferredWorkingSpace())		return;	CTexture* pHDRTarget = m_pipelineResources.m_pTexHDRTarget;	if (!CTexture::IsTextureExist(pHDRTarget))		return;	PROFILE_LABEL_SCOPE("SCENE_REFERRED_CONVERT_709_TO_AP1");	CComputeRenderPass& pass = *m_SceneReferredConvertPass;	const int width = pHDRTarget->GetWidth();	const int height = pHDRTarget->GetHeight();	if (pass.IsDirty(pHDRTarget->GetTextureID()))	{		static CCryNameTSCRC techConvert("SceneReferredConvert");		pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techConvert, 0);		pass.SetOutputUAV(0, pHDRTarget);	}	pass.BeginConstantUpdate();	{		static CCryNameR paramsName("SceneReferredParams");		// .w is the writer ceiling this pass enforces on the whole target (item 2 of the round-3		// fixes, decisions/s8-fp16-writers.md): the last point before anything downstream		// AVERAGES the buffer, so it is where a non-finite texel has to stop.		const Vec4 params((float)width, (float)height, (float)CRendererCVars::CV_r_SceneReferredDebug,		                  CRendererResources::GetSceneReferredWriterClamp());		pass.SetConstant(paramsName, params);	}	// One thread per texel; the group count is rounded up and the shader discards the padding.	const int tile = 8; // must match SCENE_REFERRED_CONVERT_TILE in HDRPostProcess.cfx	pass.SetDispatchSize((width + tile - 1) / tile, (height + tile - 1) / tile, 1);	pass.PrepareResourcesForUse(GetDeviceObjectFactory().GetCoreCommandList());	{		SScopedComputeCommandList computeCommandList(false);		pass.Execute(computeCommandList, EShaderStage_All);	}}//////////////////////////////////////////////////////////////////////////void CStandardGraphicsPipeline::ExecuteHDRPostProcessing(){	FUNCTION_PROFILER_RENDERER();	PROFILE_LABEL_SCOPE("POST_EFFECTS_HDR");	const auto& viewInfo = GetCurrentViewInfo(CCamera::eEye_Left);	PostProcessUtils().m_pView = viewInfo.viewMatrix;	PostProcessUtils().m_pProj = viewInfo.projMatrix;	PostProcessUtils().m_pViewProj = PostProcessUtils().m_pView * PostProcessUtils().m_pProj;	PostProcessUtils().m_pViewProj = ReverseDepthHelper::Convert(PostProcessUtils().m_pViewProj);	PostProcessUtils().m_pViewProj.Transpose();	if (GetStage<CRainStage>()->IsStageActive(m_renderingFlags))		GetStage<CRainStage>()->Execute();	// Note: MB uses m_pTexHDRTargetPrev to avoid doing another copy, so this should be right before the MB pass	//	// Scene-referred pipeline: this copy MUST stay in front of the working-space conversion below,	// and $HDRTargetPrev must therefore stay Rec.709. It is not a post-chain history - it is the	// texture that screen-space reflections (ScreenSpaceReflections.cpp), the water reflection	// (Water.cpp) and the SVOGI previous-frame bounce (D3D_SVO.cpp) bind NEXT frame, and all	// three consume it INSIDE the 709 lighting pass, before anything in this function runs. Feed	// them AP1 numbers read as 709 and reflections and bounce come back desaturated and	// hue-shifted, with no error anywhere. SSR's brightness limiter is additionally a PER-CHANNEL	// min against the adapted luminance, which is not basis-invariant, so it would silently start	// limiting different highlights. The only post-conversion consumer of Prev is motion blur,	// and that is handled at the copy in CMotionBlurStage::Execute().	{		m_FrameToFramePass->Execute(m_pipelineResources.m_pTexHDRTarget, m_pipelineResources.m_pTexHDRTargetPrev[GetCurrentRenderView()->GetCurrentEye()]);	}	// Rec.709 -> ACEScg. Everything upstream wrote Rec.709 scene colour; everything downstream	// reads the working space.	ExecuteSceneReferredConversion();	if (GetStage<CDepthOfFieldStage>()->IsStageActive(m_renderingFlags))		GetStage<CDepthOfFieldStage>()->Execute();	if (GetStage<CMotionBlurStage>()->IsStageActive(m_renderingFlags))		GetStage<CMotionBlurStage>()->Execute();	// Scene-referred pipeline: this is the ONE writer that lands on the far side of the	// working-space conversion with Rec.709-authored colour. Snow is near-achromatic, so the	// error is small, and per SceneReferredSpec.md D13 it is left to break visibly rather than	// switched off. (CRainStage above sits on the correct side: it writes before the copy, so it	// is converted along with everything else. CSnowStage::ExecuteDeferredSnowDisplacement()	// likewise runs before ExecuteHDRPostProcessing().) S8 breakage list.	if (GetStage<CSnowStage>()->IsStageActive(m_renderingFlags))		GetStage<CSnowStage>()->Execute();	// Half resolution downsampling	if (GetStage<CAutoExposureStage>()->IsStageActive(m_renderingFlags) ||	    GetStage<CBloomStage>()->IsStageActive(m_renderingFlags) ||	    GetStage<CSunShaftsStage>()->IsStageActive(m_renderingFlags))	{		PROFILE_LABEL_SCOPE("HALFRES_DOWNSAMPLE_HDRTARGET");		if (CRendererCVars::CV_r_HDRBloomQuality > 1)			m_HQSubResPass[0]->Execute(m_pipelineResources.m_pTexHDRTarget, m_pipelineResources.m_pTexHDRTargetScaled[0][0], true);		else			m_LQSubResPass[0]->Execute(m_pipelineResources.m_pTexHDRTarget, m_pipelineResources.m_pTexHDRTargetScaled[0][0]);	}	// Quarter resolution downsampling	if (GetStage<CAutoExposureStage>()->IsStageActive(m_renderingFlags) ||	    GetStage<CBloomStage>()->IsStageActive(m_renderingFlags))	{		PROFILE_LABEL_SCOPE("QUARTER_RES_DOWNSAMPLE_HDRTARGET");		if (CRendererCVars::CV_r_HDRBloomQuality > 0)			m_HQSubResPass[1]->Execute(m_pipelineResources.m_pTexHDRTargetScaled[0][0], m_pipelineResources.m_pTexHDRTargetScaled[1][0], CRendererCVars::CV_r_HDRBloomQuality >= 1);		else			m_LQSubResPass[1]->Execute(m_pipelineResources.m_pTexHDRTargetScaled[0][0], m_pipelineResources.m_pTexHDRTargetScaled[1][0]);	}	// reads CRendererResources::s_ptexHDRTargetScaled[1][0]	if (GetStage<CAutoExposureStage>()->IsStageActive(m_renderingFlags))		GetStage<CAutoExposureStage>()->Execute();	// reads CRendererResources::s_ptexHDRTargetScaled[1][0] and then kills it	if (GetStage<CBloomStage>()->IsStageActive(m_renderingFlags))		GetStage<CBloomStage>()->Execute();	// Lens ghosts into the HDR target. This is the point, and the reason it is not done inside	// the DOF stage: every thresholded glare source (bloom, diffraction streaks, the anamorphic	// flare, the front filter PSF, halation) has been taken from the downsampled copies above,	// and auto exposure has metered, so a ghost cannot light any of them. A ghost is a	// second-order internal reflection; a flare off one would be third order and invisible.	// Unconditional, so the ghosts appear with bloom off exactly as with bloom on. See	// LensGhostSpec.md, "Pipeline placement".	// The wave-optics glare's half-resolution layer, for exactly the same reasons as the ghosts	// below and in the same window: it is composited AFTER every glare threshold has been taken,	// so a diffraction pattern cannot halate, streak or bloom off itself. It is here rather than	// inside the bloom stage because the layer is not quarter resolution and so cannot travel	// through $HDRFinalBloom - which is also why the tone mapper's bloom weight has left its	// energy chain. A no-op unless the glare pass ran this frame. See DiffractionKernelSpec.md.	if (GetStage<CBloomStage>()->IsStageActive(m_renderingFlags))		GetStage<CBloomStage>()->ExecuteDiffractionComposite();	GetStage<CDepthOfFieldStage>()->ExecuteGhostComposite();	// writes m_graphicsPipelineResources.m_pTexSceneTargetR11G11B10F[0]	//	// Scene-referred pipeline: this is NOT a consumer of the working space, despite writing a	// target that motion blur filled with ACEScg a few passes ago - it overwrites it wholesale	// from the flare textures and never reads it. The result is composited in the LDR PostAA	// stage, i.e. after the tone map, so the flares stay display-referred on both paths and the	// primaries change cannot reach them. (They become D9's problem in S4, when the whole stock	// LDR stage is skipped under the camera, not S3's.)	if (GetStage<CLensOpticsStage>()->IsStageActive(m_renderingFlags))		GetStage<CLensOpticsStage>()->Execute();	// reads CRendererResources::s_ptexHDRTargetScaled[0][0]	if (GetStage<CSunShaftsStage>()->IsStageActive(m_renderingFlags))		GetStage<CSunShaftsStage>()->Execute();	if (GetStage<CColorGradingStage>()->IsStageActive(m_renderingFlags))		GetStage<CColorGradingStage>()->Execute();	// 0 is used for disable debugging and 1 is used to just show the average and estimated luminance, and exposure values.	if (GetStage<CToneMappingStage>()->IsDebugDrawEnabled())		GetStage<CToneMappingStage>()->ExecuteDebug();	else		GetStage<CToneMappingStage>()->Execute();}void CStandardGraphicsPipeline::Execute(){	FUNCTION_PROFILER_RENDERER();	CD3D9Renderer* pRenderer = gcpRendD3D;	CRenderView* pRenderView = GetCurrentRenderView();	auto& renderItemDrawer = pRenderView->GetDrawer();	CTexture* pZTexture = pRenderView->GetDepthTarget();	m_renderPassScheduler.SetEnabled(true);	PROFILE_LABEL_PUSH("GRAPHICS_PIPELINE");	// Generate cloud volume textures for shadow mapping. Only needs view, and needs to run before ShadowMaskgen.	GetStage<CVolumetricCloudsStage>()->ExecuteShadowGen();	if (pRenderView->GetCurrentEye() != CCamera::eEye_Right)	{		// Compute algorithms		GetStage<CComputeSkinningStage>()->Execute();		// Revert resource states to graphics pipeline		GetStage<CComputeParticlesStage>()->PreDraw();		GetStage<CComputeSkinningStage>()->PreDraw();		if (GetStage<CRainStage>()->IsRainOcclusionEnabled())			GetStage<CRainStage>()->ExecuteRainOcclusion();	}	const bool debugEnabled = GetStage<CSceneCustomStage>()->IsStageActive(m_renderingFlags) &&		!GetStage<CSceneCustomStage>()->IsDebugOverlayEnabled() &&		GetStage<CSceneCustomStage>()->ExecuteDebugger();	if (!debugEnabled)	{		// GBuffer		GetStage<CSceneGBufferStage>()->Execute();		// Issue split barriers for GBuffer		CTexture* pTextures[] = {			m_pipelineResources.m_pTexSceneNormalsMap,			m_pipelineResources.m_pTexSceneDiffuse,			m_pipelineResources.m_pTexSceneSpecular,			pZTexture		};		CDeviceGraphicsCommandInterface* pCmdList = GetDeviceObjectFactory().GetCoreCommandList().GetGraphicsInterface();		pCmdList->BeginResourceTransitions(CRY_ARRAY_COUNT(pTextures), pTextures, eResTransition_TextureRead);		// Shadow maps		if (GetStage<CShadowMapStage>()->IsStageActive(m_renderingFlags))			GetStage<CShadowMapStage>()->Execute();		// Wait for Shadow Map draw jobs to finish (also required for HeightMap AO and SVOGI)		renderItemDrawer.WaitForDrawSubmission();		if (GetStage<CDeferredDecalsStage>()->IsStageActive(m_renderingFlags))			GetStage<CDeferredDecalsStage>()->Execute();		if (GetStage<CSceneGBufferStage>()->IsGBufferVisualizationEnabled())			GetStage<CSceneGBufferStage>()->ExecuteGBufferVisualization();		// GBuffer modifiers		if (GetStage<CRainStage>()->IsDeferredRainEnabled())			GetStage<CRainStage>()->ExecuteDeferredRainGBuffer();		if (GetStage<CSnowStage>()->IsDeferredSnowEnabled())			GetStage<CSnowStage>()->ExecuteDeferredSnowGBuffer();		// Generate cloud volume textures for shadow mapping.		if (GetStage<CVolumetricCloudsStage>()->IsStageActive(m_renderingFlags))			GetStage<CVolumetricCloudsStage>()->ExecuteShadowGen();		// SVOGI		{#if defined(FEATURE_SVO_GI)			if (CSvoRenderer::GetInstance())			{				PROFILE_LABEL_SCOPE("SVOGI");				CSvoRenderer::GetInstance()->UpdateCompute(pRenderView);				CSvoRenderer::GetInstance()->UpdateRender(pRenderView);			}#endif		}		// Screen Space Reflections		if (GetStage<CScreenSpaceReflectionsStage>()->IsStageActive(m_renderingFlags))			GetStage<CScreenSpaceReflectionsStage>()->Execute();		// Height Map AO		if (GetStage<CHeightMapAOStage>()->IsStageActive(m_renderingFlags))			GetStage<CHeightMapAOStage>()->Execute();		// Screen Space Obscurance		if (GetStage<CScreenSpaceObscuranceStage>()->IsStageActive(m_renderingFlags))			GetStage<CScreenSpaceObscuranceStage>()->Execute();		if (GetStage<CTiledShadingStage>()->IsStageActive(m_renderingFlags))			GetStage<CTiledLightVolumesStage>()->Execute();		// Water volume caustics (before m_pTiledShadingStage->Execute())		GetStage<CWaterStage>()->ExecuteWaterVolumeCaustics();		SetPipelineFlags(GetPipelineFlags() | EPipelineFlags::NO_SHADER_FOG);#if DURANGO_USE_ESRAM		m_pipelineResources.m_pTexLinearDepthScaled[0]->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Transfer);		m_pipelineResources.m_pTexHDRTarget->AcquireESRAMResidency(CDeviceResource::eResCoherence_Uninitialize);		UpdatePerPassResourceSet();		UpdateRenderPasses();#endif		// Deferred shading		{			PROFILE_LABEL_SCOPE("DEFERRED_LIGHTING");			GetStage<CClipVolumesStage>()->GenerateClipVolumeInfo();			GetStage<CClipVolumesStage>()->Prepare();			GetStage<CClipVolumesStage>()->Execute();			if (GetStage<CTiledShadingStage>()->IsStageActive(m_renderingFlags))			{				GetStage<CShadowMaskStage>()->Prepare();				GetStage<CShadowMaskStage>()->Execute();				GetStage<CTiledShadingStage>()->Execute();				if (GetStage<CScreenSpaceSSSStage>()->IsStageActive(m_renderingFlags))					GetStage<CScreenSpaceSSSStage>()->Execute(m_pipelineResources.m_pTexSceneTargetR11G11B10F[0]);			}		}		{			PROFILE_LABEL_SCOPE("FORWARD Z");			GetStage<CSceneForwardStage>()->ExecuteOpaque();			// Opaque forward passes			if (GetStage<CSkyStage>()->IsStageActive(m_renderingFlags))				GetStage<CSkyStage>()->Execute(m_pipelineResources.m_pTexHDRTarget, pZTexture);		}		// Deferred ocean caustics		if (GetStage<CWaterStage>()->IsDeferredOceanCausticsEnabled())			GetStage<CWaterStage>()->ExecuteDeferredOceanCaustics();		{			// Fog			if (GetStage<CVolumetricFogStage>()->IsStageActive(m_renderingFlags))				GetStage<CVolumetricFogStage>()->Execute();			if (GetStage<CFogStage>()->IsStageActive(m_renderingFlags))				GetStage<CFogStage>()->Execute();			SetPipelineFlags(GetPipelineFlags() & ~EPipelineFlags::NO_SHADER_FOG);			// Clouds			if (GetStage<CVolumetricCloudsStage>()->IsStageActive(m_renderingFlags))				GetStage<CVolumetricCloudsStage>()->Execute();			// Water fog volumes			GetStage<CWaterStage>()->ExecuteWaterFogVolumeBeforeTransparent();		}		{			PROFILE_LABEL_SCOPE("FORWARD T");			// Transparent (below water)			GetStage<CSceneForwardStage>()->ExecuteTransparentBelowWater();			// Ocean and water volumes			GetStage<CWaterStage>()->Execute();			// Transparent (above water)			GetStage<CSceneForwardStage>()->ExecuteTransparentAboveWater();			if (GetStage<CSceneForwardStage>()->IsTransparentDepthFixupEnabled())				GetStage<CSceneForwardStage>()->ExecuteTransparentDepthFixup();			// Half-res particles			if (GetStage<CSceneForwardStage>()->IsTransparentLoResEnabled())				GetStage<CSceneForwardStage>()->ExecuteTransparentLoRes(1 + crymath::clamp<int>(CRendererCVars::CV_r_ParticlesHalfResAmount, 0, 1));		}	}	// Insert fence which is used on consoles to prevent overwriting video memory	pRenderer->InsertParticleVideoDataFence(pRenderer->GetRenderFrameID());	if (pRenderView->GetCurrentEye() == CCamera::eEye_Right ||	    !pRenderer->GetS3DRend().IsStereoEnabled() ||	    !pRenderer->GetS3DRend().RequiresSequentialSubmission())	{		GetStage<CComputeParticlesStage>()->PostDraw();	}	if (debugEnabled)		return;	if (GetStage<CSnowStage>()->IsDeferredSnowDisplacementEnabled())		GetStage<CSnowStage>()->ExecuteDeferredSnowDisplacement();	if (!(m_renderingFlags & SHDF_CUBEMAPGEN))	{		// HDR and LDR post-processing		{			// CRendererResources::s_ptexHDRTarget -> CRendererResources::s_ptexDisplayTarget (Tonemapping)			ExecuteHDRPostProcessing();			// CRendererResources::s_ptexDisplayTarget			GetStage<CSceneForwardStage>()->ExecuteAfterPostProcessHDR();#if DURANGO_USE_ESRAM			m_pipelineResources.m_pTexHDRTarget->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Abandon);			m_pipelineResources.m_pTexLinearDepth->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Abandon);			UpdatePerPassResourceSet();			UpdateRenderPasses();#endif			// CRendererResources::s_ptexDisplayTarget -> CRenderOutput->m_pColorTarget (PostAA)			// Post effects disabled, copy diffuse to color target			if (GetStage<CPostEffectStage>()->IsStageActive(m_renderingFlags))				GetStage<CPostEffectStage>()->Execute();			else				m_PostToFramePass->Execute(m_pipelineResources.m_pTexDisplayTargetDst, pRenderView->GetRenderOutput()->GetColorTarget());			// CRenderOutput->m_pColorTarget			GetStage<CSceneForwardStage>()->ExecuteAfterPostProcessLDR();		}		if (GetStage<CSceneCustomStage>()->IsSelectionHighlightEnabled())		{			GetStage<CSceneCustomStage>()->ExecuteHelpers();			GetStage<CSceneCustomStage>()->ExecuteSelectionHighlight();		}		// Display tone mapping debugging information on the screen		if (GetStage<CToneMappingStage>()->IsDebugInfoEnabled())			GetStage<CToneMappingStage>()->DisplayDebugInfo();	}	else	{		// Raw HDR copy		m_HDRToFramePass->Execute(m_pipelineResources.m_pTexHDRTarget, pRenderView->GetRenderOutput()->GetColorTarget());#if DURANGO_USE_ESRAM		m_pipelineResources.m_pTexHDRTarget->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Abandon);		m_pipelineResources.m_pTexLinearDepth->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Abandon);		UpdatePerPassResourceSet();		UpdateRenderPasses();#endif	}	if (GetStage<COmniCameraStage>()->IsStageActive(m_renderingFlags))		GetStage<COmniCameraStage>()->Execute();	if (GetStage<CVolumetricFogStage>()->IsStageActive(m_renderingFlags))		GetStage<CVolumetricFogStage>()->ResetFrame();	PROFILE_LABEL_POP("GRAPHICS_PIPELINE");	m_renderPassScheduler.SetEnabled(false);	m_renderPassScheduler.Execute(this);#if DURANGO_USE_ESRAM	m_pipelineResources.m_pTexSceneNormalsMap->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Abandon);	pZTexture->ForfeitESRAMResidency(CDeviceResource::eResCoherence_Abandon);#endif	if (CRendererCVars::CV_r_PipelineResourceDiscardAfterFrame > 1)	{		m_pipelineResources.Discard();	}}